use bytes::BufMut;
use serde_json::Value;

/// Devalue bundle (~8 KB minified) embedded in the webview shim *and*
/// in the lite-runtime QuickJS environment. Exposes
/// `globalThis.__tynd_dv__ = { parse, stringify }` so both sides can
/// roundtrip `Date` / `Map` / `Set` / `BigInt` / `URL` / `Error` / cyclic
/// refs across the IPC boundary. Regenerated by `bun run build:devalue`
/// in the core package; vendored here so host-rs stays a pure Rust crate
/// without a node_modules dependency at compile time.
pub const JS_DEVALUE: &str = include_str!("devalue.bundle.js");

/// Injected only in debug mode (`--debug` / `tynd dev`).
/// Sets `window.__tynd_dev__ = true` so framework JS can prefix its own
/// console messages with `[tynd]` without leaking the name in production.
pub const JS_DEV_FLAG: &str = "window.__tynd_dev__ = true;";

/// Fires the page-ready signal on DOMContentLoaded (skips the initial blank page).
/// Rust intercepts this to show the window only after real content is rendered,
/// eliminating the white-flash on startup.
pub const JS_PAGE_READY: &str = r#"
(function () {
  document.addEventListener("DOMContentLoaded", function () {
    var url = document.URL;
    if (url && url !== "about:blank" && !url.startsWith("data:")) {
      window.ipc.postMessage(JSON.stringify({ __tynd_page_ready: true }));
    }
  });
})();
"#;

/// Core IPC shim — creates window.__tynd__ with call/on/off/os_call.
/// Injected before any page script via with_initialization_script.
///
/// Wire format: every user payload (`call.args`, `return.value`,
/// `yield.value`, `event.payload`) rides as a string. Producers encode
/// with devalue (full runtime — Date/Map/Set/BigInt/cycles roundtrip)
/// or plain JSON (lite runtime). The shim's `_decode` tries devalue
/// first then falls back to JSON, so both producers work transparently.
/// `os_call.args` deliberately stays as a JS value because the Rust
/// host inspects fields like `url` / `width` natively.
pub const JS_SHIM: &str = r#"
(function () {
  "use strict";

  // Call IDs use UUIDs so debug traces are globally unique across reloads
  // and (for v7) sortable by creation time. Today we lean on the platform's
  // `crypto.randomUUID()` which is UUIDv4 — globally unique but not
  // time-ordered. The lite QuickJS runtime bridges to Rust (`uuid::Uuid::now_v7`)
  // via `__tynd_random_uuid__`, so backend-side ack/yield IDs are already v7.
  // Once a stable native browser UUIDv7 (or a tiny polyfill) lands, swap this
  // to a v7 generator for sortable shim-side IDs as well.
  var _pending = {};
  var _os_pending = {};
  var _listeners = {};
  var _os_listeners = {};
  // Internal logger: prefixes with [tynd] in dev mode only (window.__tynd_dev__ injected by tynd dev)
  var _log = window.__tynd_dev__
    ? function(msg) { console.error("[tynd] " + msg); }
    : function() {};

  // Decode a wire payload — devalue first (full runtime), JSON fallback
  // (lite runtime, or plain values that happen to round-trip through JSON).
  // Returns `null` on double failure so handlers don't see `undefined`.
  function _decode(s) {
    if (s == null) return null;
    var dv = window.__tynd_dv__;
    if (dv && typeof dv.parse === "function") {
      try { return dv.parse(s); } catch (_) {}
    }
    try { return JSON.parse(s); } catch (_) { return null; }
  }

  // Encode for the wire — devalue when available, JSON otherwise. The
  // call() / os fallback paths use this when sending args back to Rust.
  function _encode(v) {
    var dv = window.__tynd_dv__;
    if (dv && typeof dv.stringify === "function") {
      try { return dv.stringify(v); } catch (_) {}
    }
    try { return JSON.stringify(v); } catch (_) { return "null"; }
  }

  // Called by Rust: resolve/reject a pending backend call promise + close its stream.
  // `valueStr` is a wire-encoded payload — devalue or JSON. On error,
  // `valueStr` is the plain error message text (no encoding).
  window.__tynd_resolve__ = function (id, ok, valueStr) {
    var p = _pending[id];
    if (!p) return;
    delete _pending[id];
    if (ok) {
      var value = _decode(valueStr);
      p.finalValue = value;
      p.done = true;
      p.resolve(value);
      // Drain any async iterator waiters with { done: true }
      while (p.waiters.length) {
        var w = p.waiters.shift();
        w.resolve({ value: undefined, done: true });
      }
    } else {
      p.done = true;
      p.error = new Error(String(valueStr));
      p.reject(p.error);
      while (p.waiters.length) {
        var w2 = p.waiters.shift();
        w2.reject(p.error);
      }
    }
  };

  // Chunks are acked back to the backend every ACK_CHUNK consumed — lets
  // the backend keep ~STREAM_CREDIT chunks in-flight before it has to stall.
  // Big enough to hide round-trip latency, small enough to bound memory.
  var ACK_CHUNK = 32;
  function _ackConsume(id, p) {
    p.consumed = (p.consumed | 0) + 1;
    if (p.consumed >= ACK_CHUNK) {
      try {
        window.ipc.postMessage(JSON.stringify({ type: "ack", id: id, n: p.consumed }));
      } catch (_) {}
      p.consumed = 0;
    }
  }

  // Called by Rust: deliver one chunk from a streaming backend call.
  // `valueStr` is wire-encoded (devalue or JSON) — decoded once here.
  window.__tynd_yield__ = function (id, valueStr) {
    var p = _pending[id];
    if (!p || p.done) return;
    var value = _decode(valueStr);
    if (p.waiters.length) {
      p.waiters.shift().resolve({ value: value, done: false });
      _ackConsume(id, p);
    } else {
      p.yields.push(value);
    }
  };

  // Called by Rust: deliver a batch of yields in one call to minimize
  // `evaluate_script` overhead on bursty streams. `pairs` is an array of
  // [id, valueStr] tuples in FIFO order.
  window.__tynd_yield_batch__ = function (pairs) {
    for (var i = 0; i < pairs.length; i++) {
      window.__tynd_yield__(pairs[i][0], pairs[i][1]);
    }
  };

  // Called by Rust: resolve/reject a pending OS API call promise
  window.__tynd_os_result__ = function (id, ok, value) {
    var p = _os_pending[id];
    if (!p) return;
    delete _os_pending[id];
    if (ok) { p.resolve(value); } else { p.reject(new Error(String(value))); }
  };

  // Called by Rust: deliver a native OS event (menu click, tray click, …)
  window.__tynd_os_event__ = function (name, data) {
    var handlers = _os_listeners[name];
    if (!handlers) return;
    for (var i = 0; i < handlers.length; i++) {
      try { handlers[i](data); } catch (e) {
        _log("os event handler error: " + e);
      }
    }
  };

  // Called by Rust: dispatch a named event to frontend subscribers.
  // `payloadStr` is wire-encoded — decoded once here so each handler
  // sees a live JS value (Date / Map / Set roundtrip if devalue path).
  window.__tynd_dispatch__ = function (name, payloadStr) {
    var handlers = _listeners[name];
    if (!handlers) return;
    var payload = _decode(payloadStr);
    for (var i = 0; i < handlers.length; i++) {
      try { handlers[i](payload); } catch (e) {
        _log("event handler error: " + e);
      }
    }
  };

  window.__tynd__ = {
    // Call a backend function — returns an awaitable+iterable handle.
    // `await call(...)` -> final return value (regular async handlers, or
    // the generator's `return` value for async-generators).
    // `for await (x of call(...))` -> yielded chunks.
    call: function (fn, args) {
      // crypto.randomUUID is native in webview (browser) — UUIDv4 today;
      // migrate to v7 when a polyfill matures so call traces sort by time.
      var id = crypto.randomUUID();
      var p;
      var finalPromise = new Promise(function (res, rej) {
        p = {
          resolve: res, reject: rej,
          yields: [], waiters: [],
          done: false, error: null, finalValue: undefined, cancelled: false,
        };
      });
      _pending[id] = p;

      var iterator = {
        next: function () {
          return new Promise(function (resolve, reject) {
            if (p.yields.length) {
              resolve({ value: p.yields.shift(), done: false });
              _ackConsume(id, p);
              return;
            }
            if (p.done) {
              if (p.error) reject(p.error);
              else resolve({ value: undefined, done: true });
              return;
            }
            p.waiters.push({ resolve: resolve, reject: reject });
          });
        },
        "return": function (value) {
          if (!p.done && !p.cancelled) {
            p.cancelled = true;
            try {
              window.ipc.postMessage(JSON.stringify({ type: "cancel", id: id }));
            } catch (_) {}
          }
          return Promise.resolve({ value: value, done: true });
        },
        "throw": function (err) { return Promise.reject(err); },
      };
      iterator[Symbol.asyncIterator] = function () { return iterator; };

      var handle = {
        then: function (onF, onR) { return finalPromise.then(onF, onR); },
        "catch": function (onR) { return finalPromise["catch"](onR); },
        "finally": function (onF) { return finalPromise["finally"](onF); },
        cancel: function () { return iterator["return"](); },
      };
      handle[Symbol.asyncIterator] = function () { return iterator; };

      // Encode args via devalue (or JSON fallback) — Bun decodes the
      // same way before invoking the user's handler. The `a` field is
      // a string literal in the wire frame so the Rust shuttle can
      // forward it without parsing.
      window.ipc.postMessage(
        JSON.stringify({ type: "call", id: id, fn: fn, a: _encode(args) })
      );
      return handle;
    },

    // Subscribe to a native OS event (menu:action, tray:click, …)
    // Returns an unsubscribe function.
    os_on: function (name, handler) {
      if (!_os_listeners[name]) _os_listeners[name] = [];
      _os_listeners[name].push(handler);
      return function () {
        var list = _os_listeners[name];
        if (!list) return;
        var idx = list.indexOf(handler);
        if (idx >= 0) list.splice(idx, 1);
      };
    },

    // Call a native OS API — returns a Promise
    os_call: function (api, method, args) {
      return new Promise(function (resolve, reject) {
        // See call() above — UUIDv4 native, v7 once a polyfill lands.
        var id = "os_" + crypto.randomUUID();
        _os_pending[id] = { resolve: resolve, reject: reject };
        window.ipc.postMessage(
          JSON.stringify({ type: "os_call", id: id, api: api, method: method, args: args })
        );
      });
    },

    // Subscribe to a backend event — returns an unsubscribe function
    on: function (name, handler) {
      if (!_listeners[name]) _listeners[name] = [];
      _listeners[name].push(handler);
      return function () {
        var list = _listeners[name];
        if (!list) return;
        var idx = list.indexOf(handler);
        if (idx >= 0) list.splice(idx, 1);
      };
    },

    // Unsubscribe a specific handler
    off: function (name, handler) {
      var list = _listeners[name];
      if (!list) return;
      var idx = list.indexOf(handler);
      if (idx >= 0) list.splice(idx, 1);
    },
  };
})();
"#;

/// JSON-encode a `&str` for use as a JS literal. Falls back to an empty
/// string literal on the (impossible) serde failure so callers stay total.
#[inline]
fn js_str(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| "\"\"".into())
}

/// JSON-encode a `serde_json::Value` for use as a JS literal. Falls back
/// to `null` on the (impossible) serde failure so callers stay total.
#[inline]
fn js_val(v: &Value) -> String {
    serde_json::to_string(v).unwrap_or_else(|_| "null".into())
}

/// Build a defensive `window.__tynd_<fn>__` invocation: guards the symbol
/// with `&&` so the call is a noop when the shim hasn't loaded yet (race
/// at startup), then forwards the formatted argument list. Every
/// `eval_*` builder below threads through this single shape so adding a
/// new wire entry-point is a one-liner.
macro_rules! eval_call {
    ($fn:literal, $args:expr) => {
        format!(concat!("window.", $fn, "&&window.", $fn, "({})"), $args)
    };
}

/// Build the JS eval string that resolves/rejects a pending frontend call.
///
/// `value` is a wire-encoded payload string (devalue from full / JSON from
/// lite). On error it carries the plain message. The shim's
/// `__tynd_resolve__` decodes once before resolving the user's promise.
#[inline]
pub fn eval_resolve(id: &str, ok: bool, value: &str) -> String {
    let ok_js = if ok { "true" } else { "false" };
    eval_call!(
        "__tynd_resolve__",
        format_args!("{},{ok_js},{}", js_str(id), js_str(value))
    )
}

/// Build the JS eval string that delivers one chunk from a streaming backend call.
/// `value` is the wire-encoded payload string.
#[inline]
pub fn eval_yield(id: &str, value: &str) -> String {
    eval_call!(
        "__tynd_yield__",
        format_args!("{},{}", js_str(id), js_str(value))
    )
}

/// Build the JS eval string that delivers a batched flush of streaming chunks.
/// `pairs` is `[(id, encoded_value)]` and renders to
/// `__tynd_yield_batch__([[id,val],…])`. Single `evaluate_script` instead of
/// one per yield — cuts main-thread cost ~30x on bursty streams (e.g. 10k
/// tokens/s).
///
/// Build path uses `bytes::BytesMut` as the byte accumulator instead of
/// `String::push_str` — the buffer reserves contiguous capacity once,
/// `BufMut` writes are bounds-checked but skip the UTF-8 validation
/// `String` enforces on every push (input is provably ASCII/JSON), and
/// the final `String::from_utf8_unchecked` on the owned bytes is cheap.
/// Encoded ids are cached across consecutive entries with the same id —
/// streaming yields tend to come in same-id runs (B22), so we re-use
/// the same encoded literal instead of re-running `serde_json::to_string`
/// on every chunk. Saves ~100 µs/s @ 10k yields/s.
#[inline]
pub fn eval_yield_batch(pairs: &[(String, String)]) -> String {
    let mut out = bytes::BytesMut::with_capacity(pairs.len() * 48);
    out.put_slice(b"window.__tynd_yield_batch__&&window.__tynd_yield_batch__([");
    let mut last_id: Option<&str> = None;
    let mut last_id_encoded: String = String::new();
    for (i, (id, value)) in pairs.iter().enumerate() {
        if i > 0 {
            out.put_u8(b',');
        }
        out.put_u8(b'[');
        // Cache JSON-encoded id across consecutive same-id yields.
        if last_id.map(str::as_bytes) != Some(id.as_bytes()) {
            last_id_encoded = serde_json::to_string(id).unwrap_or_else(|_| "\"\"".into());
            last_id = Some(id.as_str());
        }
        out.put_slice(last_id_encoded.as_bytes());
        out.put_u8(b',');
        let val_enc = serde_json::to_string(value).unwrap_or_else(|_| "\"\"".into());
        out.put_slice(val_enc.as_bytes());
        out.put_u8(b']');
    }
    out.put_slice(b"])");
    // SAFETY: every byte appended above is either ASCII punctuation or
    // the output of `serde_json::to_string` (always valid UTF-8).
    unsafe { String::from_utf8_unchecked(out.to_vec()) }
}

/// Build the JS eval string that dispatches an event to frontend subscribers.
/// `payload` is the wire-encoded payload string.
#[inline]
pub fn eval_dispatch(name: &str, payload: &str) -> String {
    eval_call!(
        "__tynd_dispatch__",
        format_args!("{},{}", js_str(name), js_str(payload))
    )
}

/// Build the JS eval string that resolves/rejects a pending OS API call.
#[inline]
pub fn eval_os_result(id: &str, ok: bool, value: &Value) -> String {
    let ok_js = if ok { "true" } else { "false" };
    eval_call!(
        "__tynd_os_result__",
        format_args!("{},{ok_js},{}", js_str(id), js_val(value))
    )
}

/// Build the JS eval string that fires a native OS event to subscribed handlers.
#[inline]
pub fn eval_os_event(name: &str, data: &Value) -> String {
    eval_call!(
        "__tynd_os_event__",
        format_args!("{},{}", js_str(name), js_val(data))
    )
}

/// Source of the dev-mode backend error overlay. The `__TYND_OVERLAY_MSG__`
/// placeholder is substituted at call time with the JSON-encoded error
/// message before the script ships to the webview.
const JS_ERROR_OVERLAY: &str = include_str!("error_overlay.js");

/// Build the JS eval string that mounts a full-screen backend error overlay.
/// Dev-only — called when the backend throws during startup or reload.
#[inline]
pub fn eval_show_error_overlay(message: &str) -> String {
    JS_ERROR_OVERLAY.replace("__TYND_OVERLAY_MSG__", &js_str(message))
}

/// Build the JS eval string that removes the backend error overlay (on successful reload).
#[inline]
pub fn eval_hide_error_overlay() -> String {
    "(function(){var o=document.getElementById('__tynd_error_overlay__');if(o)o.remove();})();"
        .to_string()
}

#[cfg(test)]
mod tests {
    //! Property tests over the IPC wire-format builders.
    //!
    //! Every `eval_*` function below produces a string that the
    //! webview shim re-parses as JS — the wire is fundamentally a
    //! `String` round-trip, so the only invariant we can check
    //! mechanically is that the embedded `id` / `name` / `value`
    //! literals can be **recovered** by JSON-parsing the formatted
    //! arguments. The shim itself does this on every call (`_decode`
    //! tries devalue then JSON), so any input that round-trips here
    //! is guaranteed to round-trip on the JS side too.
    //!
    //! `proptest` generates inputs containing the full Unicode space:
    //! quotes, backslashes, NUL, embedded `</script>`, control chars,
    //! 4-byte emoji, and so on — categorically the strings that have
    //! tripped past JSON encoders in production bug reports.

    use super::*;
    use proptest::prelude::*;

    /// Pull the JSON-encoded argument list out of a generated
    /// `window.__tynd_X__&&window.__tynd_X__(<args>)` script. Returns
    /// the raw `<args>` text so the test can JSON-parse each comma-
    /// separated piece individually.
    ///
    /// `(` and `)` chars can appear in JSON string literals embedded in
    /// args, so the simple `find('(')..rfind(')')` doesn't survive
    /// `value = "("` style inputs. The shape we know: the call-site
    /// `(` is the FIRST one (no parens in the function name), and the
    /// trailing `)` is the LAST byte (the encoded args end with `"` /
    /// `null` / a number, never a paren that's ALSO the script
    /// terminator). So `find('(')` + check `script.ends_with(')')`
    /// works even when value contains either bracket.
    fn extract_args(script: &str) -> &str {
        let lparen = script.find('(').expect("eval script has '('");
        assert!(script.ends_with(')'), "eval script ends with ')'");
        &script[lparen + 1..script.len() - 1]
    }

    /// Parse the comma-separated `args` text into a stream of JSON
    /// values. Wraps the args into a `[…]` so `serde_json` does the
    /// per-token parsing — splitting on raw `','` is wrong because
    /// commas can appear inside string literals.
    fn parse_args(args: &str) -> Vec<Value> {
        let wrapped = format!("[{args}]");
        serde_json::from_str::<Vec<Value>>(&wrapped).unwrap_or_default()
    }

    proptest! {
        // Tighter case count than the proptest default (256) — these
        // tests are pure-Rust string ops, no I/O, and a few hundred
        // is enough to hit the interesting Unicode corners without
        // bloating CI walltime.
        #![proptest_config(ProptestConfig::with_cases(128))]

        #[test]
        fn eval_resolve_id_and_value_roundtrip(id in ".*", value in ".*", ok: bool) {
            let script = eval_resolve(&id, ok, &value);
            let parts = parse_args(extract_args(&script));
            prop_assert_eq!(parts.len(), 3);
            prop_assert_eq!(parts[0].as_str().unwrap(), &id);
            prop_assert_eq!(parts[1].as_bool().unwrap(), ok);
            prop_assert_eq!(parts[2].as_str().unwrap(), &value);
        }

        #[test]
        fn eval_yield_id_and_value_roundtrip(id in ".*", value in ".*") {
            let script = eval_yield(&id, &value);
            let parts = parse_args(extract_args(&script));
            prop_assert_eq!(parts.len(), 2);
            prop_assert_eq!(parts[0].as_str().unwrap(), &id);
            prop_assert_eq!(parts[1].as_str().unwrap(), &value);
        }

        #[test]
        fn eval_dispatch_name_and_payload_roundtrip(name in ".*", payload in ".*") {
            let script = eval_dispatch(&name, &payload);
            let parts = parse_args(extract_args(&script));
            prop_assert_eq!(parts.len(), 2);
            prop_assert_eq!(parts[0].as_str().unwrap(), &name);
            prop_assert_eq!(parts[1].as_str().unwrap(), &payload);
        }
    }
}
